import torch


def run(input, weight, bias, running_mean, running_var, training, momentum, eps):
    return torch.ops.aten._native_batch_norm_legit_functional.default(
        input,
        weight,
        bias,
        running_mean,
        running_var,
        training,
        momentum,
        eps,
    )


def run_correctness(input, weight, bias, running_mean, running_var, training, momentum, eps):
    outputs = torch.ops.aten._native_batch_norm_legit_functional.default(
        input.float(),
        weight.float() if weight is not None else None,
        bias.float() if bias is not None else None,
        running_mean.float(),
        running_var.float(),
        training,
        momentum,
        eps,
    )
    return tuple(output.to(input.dtype) for output in outputs)


def gen_inputs(ctx, device):
    def _rd(d):
        if isinstance(d, torch.dtype):
            return d
        return getattr(torch, str(d).replace("torch.", ""))

    rm_shape = ctx["running_mean__shape"]
    rm_dtype = _rd(ctx["running_mean__dtype"])
    rv_shape = ctx["running_var__shape"]
    rv_dtype = _rd(ctx["running_var__dtype"])
    return {
        "running_mean": torch.zeros(rm_shape, dtype=rm_dtype, device=device),
        "running_var": torch.ones(rv_shape, dtype=rv_dtype, device=device),
    }
